<template><EnterpriseAuthShell><div class="auth-panel"><h2>首次登录安全设置</h2><p class="subtitle">使用初始密码验证身份，然后设置个人密码</p><el-alert v-if="error" :title="error" type="error" :closable="false" class="mb"/><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><el-form-item label="当前初始密码" prop="current"><el-input v-model="form.current" type="password" show-password size="large" autocomplete="current-password" /></el-form-item><el-form-item label="新密码" prop="next"><el-input v-model="form.next" type="password" show-password size="large" autocomplete="new-password" /></el-form-item><el-form-item label="确认新密码" prop="confirm"><el-input v-model="form.confirm" type="password" show-password size="large" autocomplete="new-password" /></el-form-item><el-button type="primary" size="large" :loading="loading" @click="submit">保存并重新登录</el-button></el-form></div></EnterpriseAuthShell></template>
<script setup lang="ts">import{reactive,ref}from'vue';import{useRouter}from'vue-router';import type{FormInstance,FormRules}from'element-plus';import EnterpriseAuthShell from '@/components/enterprise/EnterpriseAuthShell.vue';import{useEnterpriseAuthStore}from'@/stores/enterpriseAuth';import{validatePassword}from'@/features/enterprise/validation';const auth=useEnterpriseAuthStore(),router=useRouter(),formRef=ref<FormInstance>(),loading=ref(false),error=ref(''),form=reactive({current:'',next:'',confirm:''});const rules:FormRules={current:[{required:true,message:'请输入当前初始密码',trigger:'blur'}],next:[{validator:(_r,_v,cb)=>{const message=validatePassword(form.next);message?cb(new Error(message)):cb()},trigger:'blur'}],confirm:[{validator:(_r,_v,cb)=>form.confirm===form.next?cb():cb(new Error('两次输入的密码不一致')),trigger:'blur'}]};async function submit(){if(!await formRef.value?.validate().catch(()=>false))return;loading.value=true;error.value='';try{await auth.changeInitialPassword(form.current,form.next);await router.replace('/enterprise/login')}catch(e){error.value=(e as{message?:string}).message||'修改失败'}finally{loading.value=false}}</script><style scoped>.mb{margin-bottom:20px}</style>
